import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    dept_avg_hc = {
        'Engineering': 410.1,
        'Marketing': 145.9,
        'Sales': 345.8,
        'Finance': 141.9,
        'Support': 267.5
    }

    exit_col = 'exit_event_date'
    dept_col = 'department'

    df[exit_col] = pd.to_datetime(df[exit_col], errors='coerce')

    window_start = pd.Timestamp('2025-10-25')
    window_end = pd.Timestamp('2026-10-24')

    exits_in_window = df[
        df[exit_col].notna() &
        (df[exit_col] >= window_start) &
        (df[exit_col] <= window_end)
    ]

    dept_exits = exits_in_window.groupby(dept_col).size().reset_index(name='exits')

    dept_exits['avg_hc'] = dept_exits[dept_col].map(dept_avg_hc)
    dept_exits['attrition_rate'] = dept_exits['exits'] / dept_exits['avg_hc']

    dept_exits_sorted = dept_exits.sort_values('attrition_rate', ascending=False)

    attrition_results = [
        {"name": row[dept_col], "value": round(row['attrition_rate'], 4)}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": attrition_results
    })

    dept_exit_counts = [
        {"name": row[dept_col], "value": float(row['exits'])}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "exit_count_12m_window",
        "results": dept_exit_counts
    })

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

try:
    result['assumptions'].append(
        "Attrition rate = exits in 25 Oct 2025–24 Oct 2026 window divided by each department's own average headcount from domain facts."
    )
    result['assumptions'].append(
        "Exit counts use exit_event_date column; rows with exit_event_date in the 12-month window are counted per department."
    )
    result['assumptions'].append(
        "Average headcount per department sourced from domain pack constants, not recomputed from rows."
    )
except Exception:
    pass

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
