    "missing_pct": {},
    "assumptions": [],
}

try:
    avg_hc = {"2025": 921.8, "2026": 958.5}

    exits_2025 = df[df['exit_event_date'].notna() & df['exit_event_date'].astype(str).str.startswith('2025')].copy()
    exits_2026 = df[df['exit_event_date'].notna() & df['exit_event_date'].astype(str).str.startswith('2026')].copy()

    sep_2025 = len(exits_2025)
    sep_2026 = len(exits_2026)

    rate_2025 = sep_2025 / avg_hc["2025"]
    rate_2026 = sep_2026 / avg_hc["2026"]

    result['segments'].append({
        "segment_column": "exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": [
            {"name": "2025", "value": round(rate_2025, 4)},
            {"name": "2026", "value": round(rate_2026, 4)},
        ]
    })

    result['segments'].append({
        "segment_column": "exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_count",
        "results": [
            {"name": "2025", "value": float(sep_2025)},
            {"name": "2026", "value": float(sep_2026)},
        ]
    })

    dept_rates = []
    dept_avg_hc = {"Sales": 213.0, "Operations": 118.2, "Support": 183.2,
                   "Engineering": 271.1, "Marketing": 96.6, "Finance": 76.9, "Legal": 6.0}

    for dept, dhc in dept_avg_hc.items():
        d25 = exits_2025[exits_2025['Department'] == dept]
        d26 = exits_2026[exits_2026['Department'] == dept]
        r25 = len(d25) / dhc if dhc > 0 else 0.0
        r26 = len(d26) / dhc if dhc > 0 else 0.0
        dept_rates.append({"name": f"{dept}|2025", "value": round(r25, 4)})
        dept_rates.append({"name": f"{dept}|2026", "value": round(r26, 4)})

    result['segments'].append({
        "segment_column": "Department|exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": dept_rates
    })

    lvl_avg_hc = {"L1": 302.5, "L2": 285.5, "L3": 185.2, "L4": 131.7, "L5": 60.1}
    lvl_rates = []
    for lvl, lhc in lvl_avg_hc.items():
        l25 = exits_2025[exits_2025['Job_Level'] == lvl]
        l26 = exits_2026[exits_2026['Job_Level'] == lvl]
        r25 = len(l25) / lhc if lhc > 0 else 0.0
        r26 = len(l26) / lhc if lhc > 0 else 0.0
        lvl_rates.append({"name": f"{lvl}|2025", "value": round(r25, 4)})
        lvl_rates.append({"name": f"{lvl}|2026", "value": round(r26, 4)})

    result['segments'].append({
        "segment_column": "Job_Level|exit_event_date",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": lvl_rates
    })

    vol_cats = ["Voluntary"]
    vol25 = exits_2025[exits_2025['Termination_Category'].isin(vol_cats)]
    vol26 = exits_2026[exits_2026['Termination_Category'].isin(vol_cats)]
    vrate25 = len(vol25) / avg_hc["2025"]
    vrate26 = len(vol26) / avg_hc["2026"]

    result['segments'].append({
        "segment_column": "exit_event_date",
        "metric_column": "Termination_Category",
        "aggregation": "ratio",
        "label": "voluntary_attrition_rate",
        "results": [
            {"name": "2025", "value": round(vrate25, 4)},
            {"name": "2026", "value": round(vrate26, 4)},
        ]
    })

    result['assumptions'].append("2026 attrition uses exits with exit_event_date in 2026 (up to 31 Oct 2026); 5 post-Oct-2026 dates excluded per domain rules.")
    result['assumptions'].append("Average headcount denominators are provided facts: 2025=921.8, 2026=958.5.")
    result['assumptions'].append("Voluntary attrition excludes retirements; only Termination_Category=='Voluntary' rows counted.")
    result['assumptions'].append("Department and Job_Level attrition rates use their own average headcount denominators from domain facts.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

